CREATE TABLE `business_unit_operating_hours` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`unit_id` BIGINT UNSIGNED NOT NULL,`weekday` TINYINT UNSIGNED NOT NULL,`starts_at` CHAR(5) NOT NULL,`ends_at` CHAR(5) NOT NULL,`active` BOOLEAN NOT NULL DEFAULT TRUE,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `business_unit_operating_hours_public_id_key` (`public_id`),INDEX `business_unit_operating_hours_tenant_id_unit_id_weekday_ac_idx` (`tenant_id`,`unit_id`,`weekday`,`active`),CONSTRAINT `business_unit_operating_hours_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `business_unit_operating_hours_unit_id_fkey` FOREIGN KEY (`unit_id`) REFERENCES `business_units`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
